**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int sumaCyfr(int n) {
    int suma = 0;
    while (n > 0) {
        suma += n % 10;
        n /= 10;
    }
    return suma;
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        int sc = sumaCyfr(liczba);
        int reszta = liczba % sc;
        cout << liczba << ": suma cyfr = " << sc << ", "
             << liczba << " % " << sc << " = " << reszta;
        if (reszta == 0) {
            cout << " -> TAK" << endl;
            ile++;
        } else {
            cout << " -> NIE" << endl;
        }
    }
    cout << "Liczb podzielnych przez sume cyfr: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Suma cyfr obliczana klasycznie operatorem `%` i `/`. Nastepnie sprawdzamy podzielnosc oryginalnej liczby przez te sume. Uwaga: suma cyfr > 0 dla liczb dodatnich, wiec nie ma ryzyka dzielenia przez zero.

